public with sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // Validate and normalise base currency
        String normalisedBase = normaliseAndValidateCurrency(baseCurrency, 'Base currency');

        // Validate and normalise quote currencies
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currencies set cannot be null or empty.');
        }

        Set<String> normalisedQuotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalisedQuote = normaliseAndValidateCurrency(quote, 'Quote currency');
            normalisedQuotes.add(normalisedQuote);
        }

        // Build symbols parameter (comma-separated)
        String symbols = String.join(new List<String>(normalisedQuotes), ',');

        // Make callout with retry logic
        HttpResponse response = makeCallout(normalisedBase, symbols);
        Integer statusCode = response.getStatusCode();

        // Retry once on 503
        if (statusCode == 503) {
            response = makeCallout(normalisedBase, symbols);
            statusCode = response.getStatusCode();
        }

        // Check final status
        if (statusCode != 200) {
            throw new ExchangeRateException('Callout failed with HTTP status ' + statusCode);
        }

        // Parse response
        return parseResponse(response.getBody(), normalisedQuotes);
    }

    private static String normaliseAndValidateCurrency(String currencyCode, String fieldName) {
        if (currencyCode == null) {
            throw new ExchangeRateException(fieldName + ' cannot be null.');
        }

        String normalised = currencyCode.trim().toUpperCase();

        if (!Pattern.matches('[A-Z]{3}', normalised)) {
            throw new ExchangeRateException(fieldName + ' must be exactly three letters A-Z after normalisation: ' + normalised);
        }

        return normalised;
    }

    private static HttpResponse makeCallout(String base, String symbols) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:FB_Exchange_Rates/v1/latest');
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        // Add query parameters
        String url = req.getEndpoint() + '?base=' + EncodingUtil.urlEncode(base, 'UTF-8') 
                           + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8');
        req.setEndpoint(url);

        Http http = new Http();
        return http.send(req);
    }

    private static Map<String, Decimal> parseResponse(String body, Set<String> requestedQuotes) {
        Map<String, Decimal> result = new Map<String, Decimal>();

        try {
            // Parse JSON
            Map<String, Object> root = (Map<String, Object>) JSON.deserializeUntyped(body);

            if (!root.containsKey('rates')) {
                throw new ExchangeRateException('Response missing "rates" object.');
            }

            Map<String, Object> rates = (Map<String, Object>) root.get('rates');

            // Extract requested rates
            for (String quote : requestedQuotes) {
                if (!rates.containsKey(quote)) {
                    throw new ExchangeRateException('Rate for requested currency ' + quote + ' not found in response.');
                }

                Object rateObj = rates.get(quote);
                Decimal rate;

                if (rateObj instanceof Decimal) {
                    rate = (Decimal) rateObj;
                } else if (rateObj instanceof Double) {
                    rate = Decimal.valueOf((Double) rateObj);
                } else if (rateObj instanceof Integer) {
                    rate = Decimal.valueOf((Integer) rateObj);
                } else if (rateObj instanceof Long) {
                    rate = Decimal.valueOf((Long) rateObj);
                } else if (rateObj instanceof String) {
                    rate = Decimal.valueOf((String) rateObj);
                } else {
                    throw new ExchangeRateException('Rate for currency ' + quote + ' is not a valid number.');
                }

                result.put(quote, rate);
            }

        } catch (System.JSONException e) {
            throw new ExchangeRateException('Failed to parse response body: ' + e.getMessage());
        } catch (ExchangeRateException e) {
            throw e;
        } catch (Exception e) {
            throw new ExchangeRateException('Unexpected error parsing response: ' + e.getMessage());
        }

        return result;
    }
}
