@IsTest
public with sharing class AddressVerificationServiceTest {

    // ------------------------------------------------------------
    // Mock that captures the request for assertion and returns 200 VERIFIED
    // ------------------------------------------------------------
    private class VerifiedMock implements HttpCalloutMock {
        public HttpRequest capturedRequest;
        public HTTPResponse respond(HTTPRequest req) {
            this.capturedRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(200);
            res.setBody('{"status":"VERIFIED","address":{"street":"123 Main St","city":"Springfield","postalCode":"12345","country":"USA"}}');
            return res;
        }
    }

    // ------------------------------------------------------------
    // Mock that returns 200 CORRECTED with a corrected address
    // ------------------------------------------------------------
    private class CorrectedMock implements HttpCalloutMock {
        public HttpRequest capturedRequest;
        public HTTPResponse respond(HTTPRequest req) {
            this.capturedRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(200);
            res.setBody('{"status":"CORRECTED","address":{"street":"456 Oak Ave","city":"Shelbyville","postalCode":"67890","country":"USA"}}');
