public with sharing class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        validateInputs(objectApiName, fieldApiName);

        Schema.SObjectType sObjectType = findSObjectType(objectApiName);
        if (sObjectType == null) {
            throw new PicklistServiceException('Object not found: ' + objectApiName);
        }

        Schema.DescribeSObjectResult describeSObject = sObjectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = describeSObject.fields.getMap();

        Schema.SObjectField field = findField(fieldMap, fieldApiName);
        if (field == null) {
            throw new PicklistServiceException('Field not found on object ' + describeSObject.getName() + ': ' + fieldApiName);
        }

        Schema.DescribeFieldResult describeField = field.getDescribe();
        Schema.DisplayType fieldType = describeField.getType();

        if (fieldType != Schema.DisplayType.Picklist && fieldType != Schema.DisplayType.MultiSelectPicklist) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + describeField.getName());
        }

        List<Schema.PicklistEntry> picklistValues = describeField.getPicklistValues();
        List<Option> options = new List<Option>();

        for (Schema.PicklistEntry entry : picklistValues) {
            if (entry.isActive()) {
                options.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }

        return options;
    }

    private static void validateInputs(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name cannot be null or blank');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name cannot be null or blank');
        }
    }

    private static Schema.SObjectType findSObjectType(String objectApiName) {
        String normalizedInput = objectApiName.trim().toLowerCase();
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

        for (String key : globalDescribe.keySet()) {
            if (key.toLowerCase().equals(normalizedInput)) {
                return globalDescribe.get(key);
            }
        }
        return null;
    }

    private static Schema.SObjectField findField(Map<String, Schema.SObjectField> fieldMap, String fieldApiName) {
        String normalizedInput = fieldApiName.trim().toLowerCase();

        for (String key : fieldMap.keySet()) {
            if (key.toLowerCase().equals(normalizedInput)) {
                return fieldMap.get(key);
            }
        }
        return null;
    }
