        // Build the contact sub-query using ContactsSelector's field list
        fflib_QueryFactory contactSubQuery = new fflib_QueryFactory(Contact.SObjectType)
            .selectFields(contactsSelector.getSObjectFieldList())
            .setCondition('AccountId IN :accountIds');

