        Integer chunkSize = 100;
        for (Integer i = 0; i < newAccountIds.size(); i += chunkSize) {
            List<Id> chunk = newAccountIds.subList(i, Math.min(i + chunkSize, newAccountIds.size()));
            System.enqueueJob(new ErpCustomerSync(chunk));
        }
    }
