public with sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each supplied Opportunity.
     *
     * Uses a single Database.insert with allOrNone=false to avoid the
     * 150 DML-statement governor limit while still capturing per-record
     * failures caused by validation rules or other exceptions.
     *
     * @param opportunityIds  Ids of the Opportunities that need a follow-up task
     * @return                Set of Opportunity Ids whose task could NOT be created;
     *                        empty set when every task succeeded
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Bulk-query the fields we need so we only hit the database once.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        Date dueDate = Date.today().addDays(7);
        List<Task> tasksToInsert = new List<Task>();
        // Keep a parallel list of opportunity Ids so we can map SaveResult back to the Opportunity.
        List<Id> oppIdByIndex = new List<Id>();

        for (Opportunity opp : opportunities) {
            tasksToInsert.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = dueDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            oppIdByIndex.add(opp.Id);
        }

        // Single DML statement, partial success allowed.
        List<Database.SaveResult> results = Database.insert(tasksToInsert, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(oppIdByIndex[i]);
                // In production you would likely log this to a custom log object
                // or platform event instead of debug.
                System.debug(LoggingLevel.ERROR,
                    'FollowUpTaskService: failed to create task for Opportunity ' +
                    oppIdByIndex[i] + ' – ' + results[i].getErrors()[0].getMessage());
            }
        }

        return failedOpportunityIds;
    }
}
