public with sharing class AccountRatingService {

    /**
     * Recalculates the Account.Rating for a set of accounts based on their open Opportunities.
     * Called asynchronously via @future so Opportunity DML stays fast.
     *
     * Rating rules:
     *  - Hot   : ≥1 open Opportunity with Amount ≥ 100,000
     *  - Warm  : open Opportunities exist, but none ≥ 100,000
     *  - Cold  : no open Opportunities
     *
     * @param accountIds Accounts to recalculate. Empty set is a no-op.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) return;

        // Remove any nulls that might have slipped in
        accountIds.remove(null);
        if (accountIds.isEmpty()) return;

        // Query all open opportunities for these accounts in one go.
        // Group by AccountId so we can decide the rating per account.
        List<AggregateResult> agg = [
            SELECT AccountId,
                   MAX(Amount) maxAmt,
                   COUNT(Id) cnt
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ];

        // Map AccountId -> new Rating
        Map<Id, String> newRatings = new Map<Id, String>();

        // Default all requested accounts to Cold
        for (Id aid : accountIds) {
            newRatings.put(aid, 'Cold');
        }

        for (AggregateResult ar : agg) {
            Id aid = (Id) ar.get('AccountId');
            Decimal maxAmt = (Decimal) ar.get('maxAmt');
            if (maxAmt != null && maxAmt >= 100000) {
                newRatings.put(aid, 'Hot');
            } else {
                newRatings.put(aid, 'Warm');
            }
        }

        // Build list of Accounts to update (only Rating field)
        List<Account> toUpdate = new List<Account>();
        for (Id aid : newRatings.keySet()) {
            toUpdate.add(new Account(Id = aid, Rating = newRatings.get(aid)));
        }

        // Update in one DML; partial success is fine — job is idempotent.
        try {
            Database.update(toUpdate, false);
        } catch (Exception e) {
            // Log and swallow; next change will re-trigger.
            System.debug(LoggingLevel.ERROR,
                'AccountRatingService failed to update Accounts ' + newRatings.keySet() + ': ' + e.getMessage());
        }
    }
}
