public with sharing class CaseSurveyJob implements Queueable {
    private final List<Id> caseIds;

    // Primary constructor for batched enqueue (up to 50 cases per job)
    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    // Backward-compatible single-case constructor (used if any other code enqueues individually)
    public CaseSurveyJob(Id caseId) {
        this.caseIds = new List<Id>{ caseId };
    }

    public void execute(QueueableContext context) {
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Query cases with ContactId
        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
        ];

        List<Task> tasksToInsert = new List<Task>();
        for (Case c : cases) {
            // Cases without a contact get no task
            if (c.ContactId == null) {
                continue;
            }
            tasksToInsert.add(new Task(
                WhatId = c.Id,
                WhoId = c.ContactId,
                Subject = 'CSAT survey: ' + c.CaseNumber,
                ActivityDate = Date.today().addDays(2),
                Status = 'Not Started'
            ));
        }

        if (!tasksToInsert.isEmpty()) {
            // allOrNone=false ensures one task failure doesn't roll back the others
            Database.insert(tasksToInsert, false);
        }
    }
}
