import { LightningElement, wire, track } from 'lwc';
import { MessageContext, subscribe, unsubscribe, APPLICATION_SCOPE, publish } from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @track recordId = null;
    subscription = null;
    messageContext = null;

    @wire(MessageContext)
    wiredMessageContext(context) {
        this.messageContext = context;
        this.subscribeToChannel();
    }

    connectedCallback() {
        // In case wire already fired before connectedCallback
        if (this.messageContext && !this.subscription) {
            this.subscribeToChannel();
        }
    }

    disconnectedCallback() {
        this.unsubscribeFromChannel();
    }

    subscribeToChannel() {
        if (this.messageContext && !this.subscription) {
            this.subscription = subscribe(
                this.messageContext,
                ACCOUNT_SELECTED_CHANNEL,
                (message) => this.handleMessage(message),
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    unsubscribeFromChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        if (message && message.recordId !== undefined) {
            this.recordId = message.recordId;
        }
    }

    handleClearClick() {
        if (this.messageContext) {
            publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
        }
    }
