import { LightningElement, api, track } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import LightningConfirm from 'lightning/confirm';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    _opportunities = [];

    @track _localOpportunities = [];

    @api
    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = value || [];
        // Create a local copy to avoid mutating parent's array
        this._localOpportunities = [...this._opportunities];
    }

    get columns() {
        return [
            { label: 'Name', fieldName: 'Name', type: 'text' },
            { label: 'Stage', fieldName: 'StageName', type: 'text' },
            { label: 'Amount', fieldName: 'Amount', type: 'currency' },
            {
                type: 'action',
                typeAttributes: {
                    rowActions: [
                        { label: 'View', name: 'view' },
                        { label: 'Edit', name: 'edit' },
                        { label: 'Delete', name: 'delete' }
                    ]
                }
            }
        ];
    }

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        objectApiName: 'Opportunity',
                        actionName: 'view'
                    }
                });
                break;

            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        objectApiName: 'Opportunity',
                        actionName: 'edit'
                    }
                });
                break;

            case 'delete':
                this.handleDelete(row);
                break;
        }
    }

    async handleDelete(row) {
        const confirmed = await LightningConfirm.open({
            message: `Are you sure you want to delete "${row.Name}"?`,
            variant: 'header',
            label: 'Confirm Delete',
            theme: 'error'
        });

        if (!confirmed) {
            return;
        }

        try {
            await deleteRecord(row.Id);

            // Remove from local copy only
            this._localOpportunities = this._localOpportunities.filter(opp => opp.Id !== row.Id);

            this.dispatchEvent(new ShowToastEvent({
                title: 'Opportunity deleted',
                variant: 'success'
            }));
        } catch (error) {
            const errorMessage = error.body?.message || 'An error occurred while deleting the opportunity.';
            this.dispatchEvent(new ShowToastEvent({
                title: 'Delete failed',
                message: errorMessage,
                variant: 'error'
            }));
        }
    }
}
