public with sharing class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInputs(contactId, amount, giftDate);

        Contact donor = getContactWithHousehold(contactId);
        List<Contact> householdMembers = getHouseholdMembers(donor.AccountId);

        Opportunity gift = createOpportunity(donor, householdMembers, amount, giftDate);
        insert gift;

        createContactRoles(gift.Id, donor.Id, householdMembers);
        createPayment(gift.Id, amount, giftDate);

        return gift.Id;
    }

    private static void validateInputs(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null) {
            throw new IllegalArgumentException('Contact ID cannot be null');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date cannot be null');
        }
    }

    private static Contact getContactWithHousehold(Id contactId) {
        Contact c = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (c == null) {
            throw new IllegalArgumentException('Contact not found');
        }
        if (c.AccountId == null) {
            throw new IllegalArgumentException('Contact is not associated with a household account');
        }
        return c;
    }

    private static List<Contact> getHouseholdMembers(Id householdAccountId) {
        return [
            SELECT Id, FirstName, LastName
            FROM Contact
            WHERE AccountId = :householdAccountId
        ];
    }

    private static Opportunity createOpportunity(
        Contact donor,
        List<Contact> householdMembers,
        Decimal amount,
        Date giftDate
    ) {
        String oppName = donor.FirstName + ' ' + donor.LastName + ' Donation ' +
            String.valueOf(giftDate);

        return new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won',
            npsp__Primary_Contact__c = donor.Id
        );
    }

    private static void createContactRoles(Id opportunityId, Id donorId, List<Contact> householdMembers) {
        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();

        roles.add(new OpportunityContactRole(
            OpportunityId = opportunityId,
            ContactId = donorId,
            Role = 'Donor',
            IsPrimary = true
        ));

        for (Contact member : householdMembers) {
            if (member.Id != donorId) {
                roles.add(new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId = member.Id,
                    Role = 'Household Member',
                    IsPrimary = false
                ));
            }
        }

        if (!roles.isEmpty()) {
            insert roles;
        }
    }

    private static void createPayment(Id opportunityId, Decimal amount, Date giftDate) {
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c = opportunityId,
            npe01__Payment_Amount__c = amount,
            npe01__Payment_Date__c = giftDate,
            npe01__Scheduled_Date__c = giftDate,
            npe01__Paid__c = true
        );
        insert payment;
    }
}
