public with sharing class RecordAccessService {

    /**
     * Returns the subset of recordIds that the running user can edit.
     * Uses UserRecordAccess.HasEditAccess to determine edit access.
     * Handles up to 2,000 IDs across multiple objects in batches of 200
     * to stay within UserRecordAccess query limits and the 20-query ceiling.
     *
     * @param recordIds Set of record IDs (may be null, empty, or up to 2,000 IDs)
     * @return Set of IDs the user can edit (never null)
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Convert to list for predictable chunking
        List<Id> idList = new List<Id>(recordIds);
        final Integer CHUNK_SIZE = 200; // UserRecordAccess max rows per query

        for (Integer i = 0; i < idList.size(); i += CHUNK_SIZE) {
            Integer end = Math.min(i + CHUNK_SIZE, idList.size());
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < end; j++) {
                chunk.add(idList[j]);
            }

            List<UserRecordAccess> uraList = [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                AND RecordId IN :chunk
            ];

            for (UserRecordAccess ura : uraList) {
                if (ura.HasEditAccess) {
                    editable.add(ura.RecordId);
                }
            }
            // Records not returned by the query have no read access → no edit access
        }

        return editable;
    }
}
