public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(triggerOld);
        List<Task> tasksToCreate = new List<Task>();

        for (Opportunity opp : triggerNew) {
            // Process only on the first after-update execution in this transaction.
            // The framework increments idToNumberOfTimesSeenAfterUpdate before invoking actions.
            // First execution → 1, second (rounding re-update) → 2, etc.
            Integer timesSeen = TriggerBase.idToNumberOfTimesSeenAfterUpdate.get(opp.Id);
            if (timesSeen != null && timesSeen > 1) {
                continue;
            }

            Opportunity oldOpp = oldMap.get(opp.Id);
            if (oldOpp != null && opp.Amount != oldOpp.Amount) {
                tasksToCreate.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
